sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        var messageBody = '';
        var clientcomments = '';
        if (current.servicenow_template_name == 'sn-16' || current.servicenow_template_name == 'sn-17' || current.servicenow_template_name == 'sn-18') {
            messageBody = '{' + '"paragraph"' + ':' + current.para + ',\n' + '"table":[' + current.table_array + ']}';
            var records = JSON.parse(messageBody);
            var table = records.table;
            table.sort(function(column1, column2) {
                var basketIdComparison = (column1["Basket ID"] + "").localeCompare(column2["Basket ID"] + "");
                if (basketIdComparison !== 0) return basketIdComparison;
                //var currencyComparison = (a["Currency"] + "").localeCompare(b["Currency"] + "");
                //if (currencyComparison !== 0) return currencyComparison;
                var mismatchedComparison = (column1["Mismatched Fields"] + "").localeCompare(column2["Mismatched Fields"] + "");
                if (mismatchedComparison !== 0) return mismatchedComparison;
                var valueDateComparison = new Date(column1["Value Date"] + "") - new Date(column2["Value Date"] + "");
                if (valueDateComparison !== 0) return valueDateComparison;
                var dirOrder = {
                    "S": 0,
                    "B": 1
                };//as per requirement sell should first
                var directionComparison = dirOrder[column1["Direction (B/S)"]] - dirOrder[column2["Direction (B/S)"]];
                if (directionComparison !== 0) return directionComparison;
                var instrumentIDComparison = (column1["RIC"] + "").localeCompare(column2["RIC"] + "");
                if (instrumentIDComparison !== 0) return instrumentIDComparison;

            });
            records.table = table;
            var sortedJSON = JSON.stringify(records);
            messageBody = sortedJSON;
        } else if (current.servicenow_template_name == 'sn-12' || current.servicenow_template_name == 'sn-13') {
            messageBody = '{' + '"paragraph"' + ':' + current.para + ',\n' + '"table":[' + current.table_array + ']}';
        } else {
            messageBody = '{' + '"paragraph"' + ':' + current.para + ',\n' + '"table":' + current.table_array + '}';
        }


        var child = new GlideRecord('x_hsb11_mss_smh_child_aggregated_trade_chat_queue');
        var childCount = 0;
        child.addQuery('trade_case_task', current.servicenow_task_id);
        child.query();
        if (child.next()) {
            var ga = new GlideAggregate('x_hsb11_mss_smh_child_aggregated_trade_chat_queue');
            ga.addQuery('parent', child.parent);
            ga.addAggregate('COUNT');
            ga.query();
            if (ga.next()) {
                childCount = ga.getAggregate('COUNT');
            }
        }
        var tradetask = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task');
        tradetask.addQuery('number', current.servicenow_task_id);
        tradetask.query();
        if (tradetask.next()) {

            var caserec = new GlideRecord('x_hsb11_hsbc_mss_t_trade_case');
            caserec.addQuery('number', tradetask.getDisplayValue('parent'));
            caserec.query();
            if (caserec.next()) {
                clientcomments = caserec.getDisplayValue('client_comments');
            }
        }
        var replace1 = messageBody.replaceAll("AA12", current.exchange);
        var replace2 = replace1.replaceAll("BB34", current.client);
        var replace3 = replace2.replaceAll("CC56", current.trade_date);
        var replace4 = replace3.replaceAll("DD78", current.value_date);
        if ((current.servicenow_template_name == 'sn-16' || current.servicenow_template_name == 'sn-17' || current.servicenow_template_name == 'sn-18') && childCount == 1) {
            replace4 = replace4.replaceAll("EE90 ", '');
            replace4 = replace4.replaceAll("(ES) ", '');
            replace4 = replace4.replaceAll("(AGGREGATED TRADES)", '');
        }
        var replace5 = replace4.replaceAll("EE90", childCount);
        var replace6 = replace5.replaceAll("EE0910", clientcomments);
        current.message_body = replace6;
        current.update();
    } catch (e) {
        gs.error("[BR][HSBC-Concatinating symphony templates]: " + " " + e.message + "\n" + e.stack);
    }


})(current, previous);
